public void insert()
{
    next insert();

    PurchAgreementHeaderHistory::avaCopyMarkup(this.avaGetSalesAgreementHeader(), this);
}

/// <summary>
/// Copies <c>MarkupTrans</c> records from origin to destination records
/// </summary>
/// <param name = "_fromHeader">Common - normally SalesAgreementHeader</param>
/// <param name = "_toHeader">Common - normally SalesAgreementHeaderHistory</param>
public static void avaCopyMarkup(Common _fromHeader, Common _toHeader)
{
    Markup::copy(NoYes::No, _fromHeader, _toHeader);
}

/// <summary>
/// Gets related <c>SalesAgreementHeader</c> record
/// </summary>
/// <returns>SalesAgreementHeader</returns>
public SalesAgreementHeader avaGetSalesAgreementHeader()
{
    return SalesAgreementHeader::find(this.AgreementHeader);
}

/// <summary>
/// Finds <c>SalesAgreementHeaderHistory</c> records
/// </summary>
/// <param name = "_recId">RecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>SalesAgreementHeaderHistory</returns>
public static SalesAgreementHeaderHistory avaFindRecId(RecId _recId, boolean _selectForUpdate = false)
{
    SalesAgreementHeaderHistory avaHeaderHistory;

    if(_selectForUpdate)
    {
        avaHeaderHistory.selectForUpdate(_selectForUpdate);
    }

    select firstonly avaHeaderHistory
        where avaHeaderHistory.RecId == _recId;

    return avaHeaderHistory;
}
